"""Package SNDK's reviewed mixed-date conditional research; never modify originals.
No downloaded filings, transcripts, OCR extracts or raw corporate documents ship.
"""
import copy,csv,hashlib,html,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SRC=Path('/workspace/shared/atlas-research/company-onboarding/SNDK')
OUT=ROOT/'dist/data/incremental-SNDK-2026-10-19-v3';OUT.mkdir(parents=True,exist_ok=True)
BASE='./data/'+OUT.name+'/'
def read(p):return json.loads((SRC/p).read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):
 q=OUT/p;q.parent.mkdir(parents=True,exist_ok=True);q.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
inputs=read('v3/model-inputs.json');outputs=read('v3/model-output.json');audit=read('independent-audit-v3/recheck-results.json');ledger=read('source-manifest.json')
assert audit['independent_cases_replayed']==114 and audit['mutation_test']=='PASS'
assert all(o['status']=='VALID_CONDITIONAL_RESEARCH' and len(o['rows'])==10 for o in outputs)
urls={s['file']:s['url'] for s in ledger}
def cleantext(s):
 s=s.replace(str(SRC)+'/','').replace(str(SRC),'SNDK research archive')
 return re.sub(r'(?:/workspace/|/home/|/tmp/|file://)[^\s\"\'<>`]+','[private execution path omitted]',s)
def clean(x):
 if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
 if isinstance(x,list):return [clean(v) for v in x]
 return cleantext(x) if isinstance(x,str) else x
allowed=['RESEARCH.md','history.csv','guidance-track-record.csv','model-inputs.json','model-output.json','forecast.csv','sensitivity.json','source-manifest.json']
for folder in ['v2','v3','independent-audit-v1','independent-audit-v2','independent-audit-v3']:
 allowed += [p.relative_to(SRC).as_posix() for p in sorted((SRC/folder).glob('*')) if p.suffix in ('.md','.json','.csv')]
allowed+=['v3/replay_dcf.py','v3/test_model.py','v3/test_claim_funding.py','v3/build_extra_sensitivities.py']
manifest=[]
for p in allowed:
 q=OUT/p;q.parent.mkdir(parents=True,exist_ok=True)
 if p.endswith('.json'):write(p,clean(read(p)))
 else:q.write_text(cleantext((SRC/p).read_text()))
 manifest.append({'sourceArtifact':p,'packagedArtifact':p,'sourceSHA256':sha(SRC/p),'packagedSHA256':sha(q)})
write('conditional-outputs-v3.json',outputs)
history=[]
for r in csv.DictReader((SRC/'history.csv').read_text().splitlines()):
 fy=int(r['fiscal_year']);num=lambda k:float(r[k]) if r[k] else None
 rev=num('revenue_usd_m');ebit=num('ebit_usd_m');source=r['source'].split()[0]
 history.append({'period':f'FY{fy}','fiscalYear':fy,'fiscalEnd':{2025:'2025-06-27',2026:'2026-07-03'}.get(fy),'revenue':rev,'canonicalOperatingEBIT':ebit,'operatingMargin':None if ebit is None else ebit/rev,'grossProfit':num('gross_profit_usd_m'),'cashFromOperations':num('cfo_usd_m'),'ownCapex':num('own_capex_usd_m'),'DA':num('da_usd_m'),'SBC':num('sbc_usd_m'),'comparableIssuerAnnual':fy>=2023,'coverage':'issuer_or_carveout' if fy>=2023 else 'predecessor_product_or_segment_only','comparability':r['comparability'],'sourceUrl':urls[source],'fieldProvenance':r['source'],'basis':'Sandisk issuer/carve-out' if fy>=2023 else 'WDC flash predecessor; not standalone Sandisk'})
write('history-v3.json',history)
guidance=[]
for r in csv.DictReader((SRC/'guidance-track-record.csv').read_text().splitlines()):
 for k in list(r):
  if k not in ('target_period','guidance_date','guidance_source','actual_source'):r[k]=float(r[k]) if r[k] else None
 r['guide_url']=urls[r['guidance_source']];r['actual_url']=urls.get(r['actual_source']);r['status']='observed' if r['revenue_actual_m'] is not None else 'pending_not_scored';guidance.append(r)
write('guidance-comparisons-v3.json',guidance)
pairs={
'summary':('Sandisk sells NAND storage products, including enterprise SSDs, edge devices and consumer storage. The v3 illustrative conditional values are $1,630.75 structural reset, $358.44 partial normalization and $40.47 contract/cycle stress per 155 million proxy shares. No probabilities are assigned. These are mixed-date research exhibits, not current fair values, trading targets or recommendations.','Sandisk 提供 NAND 存储产品，涵盖企业级 SSD、边缘设备与消费存储。v3 条件示例按 1.55 亿代理股数计算，结构性重置、部分正常化、合同／周期压力情景分别为每股 1,630.75、358.44、40.47 美元。情景没有概率权重，仅为混合日期研究展示，不是当前公允价值、交易目标或投资建议。'),
'scope':('The discount origin and financial bridge are July 3, 2026. Information runs through October 18 PDT / October 19 UTC and includes later guidance. Annual year-end discount factors are 1–10, with FY2027–36 inputs and a FY2037 terminal stage. No October bridge is invented. Current valuation, historical backtest, upside and ranking eligibility are all false, even if a market quote is supplied.','折现起点及财务桥接基准为 2026 年七月三日，信息截至太平洋时间十月十八日／UTC 十月十九日，包含后续指引。2027–2036 财年按年末第 1–10 年折现，2037 财年为终值阶段。没有虚构十月桥接。即使输入股价，当前估值、历史回测、上涨空间及排名资格仍全部关闭。'),
'business':('FY2026 datacenter/edge/consumer revenue was $5,153m/$12,160m/$2,935m (25.45%/60.05%/14.50%). Do not label all sales AI revenue or confuse NAND with HBM DRAM. Controllers, firmware, enterprise qualification and Kioxia manufacturing are important; Samsung, SK hynix, Micron, Kioxia and YMTC compete. High Bandwidth Flash has no separate modeled revenue.','2026 财年数据中心／边缘／消费收入为 5,153／12,160／2,935 百万美元，占 25.45%／60.05%／14.50%。不可将全部收入称为 AI 收入，或混淆 NAND 与 HBM DRAM。控制器、固件、企业认证及铠侠制造关系重要；竞争者包括三星、SK 海力士、美光、铠侠及长江存储。模型未单列高带宽闪存收入。'),
'history':('Ten FY2017–26 slots include only four issuer/carve-out years, FY2023–26. FY2017–19 are WDC flash-product sales; FY2020–22 segment gross profit omits corporate allocations. Earlier standalone EBIT, cash flow, debt and dilution remain unavailable. FY2023 carve-out sales $6,086m differ from WDC segment $6,063m. FY2026 is the first full standalone year and has 53 weeks versus 52 in FY2025. The old pre-2016 Sandisk is not this issuer.','2017–2026 财年十个位置仅有 2023–2026 四个发行人／分拆财务年度。2017–2019 为西部数据闪存产品收入；2020–2022 分部毛利不含总部费用分配。更早的独立营业利润、现金流、债务及稀释资料仍缺失。2023 分拆收入 6,086 百万美元不同于分部 6,063。2026 为首个完整独立年度，共 53 周，2025 为 52 周。2016 年前旧 Sandisk 不是本发行人。'),
'profitability':('FY2026 revenue/GAAP EBIT/CFO were $20,248m/$12,389m/$11,671m. Price/mix rather than bits alone explains extraordinary growth. FY2025 EBIT includes $1,830m goodwill impairment: adding only that item to -$1,377m gives $453m, not the issuer non-GAAP $689m. Nonoperating Nanya gains $808m do not enter FCFF. Future SBC and R&D remain operating expenses, without an SBC add-back or a fabricated R&D asset.','2026 财年收入／GAAP 营业利润／经营现金流为 20,248／12,389／11,671 百万美元。超常增长不能仅由位元增长解释，价格与组合至关重要。2025 营业亏损 1,377 含商誉减值 1,830；只加回该项得 453，并非公司非 GAAP 689。南亚股权非经营收益 808 不进入 FCFF。未来股权薪酬及研发继续费用化，不加回股权薪酬，也不虚构研发资产。'),
'guidance':('Four observed standalone quarterly pairs, FY2026 Q1–Q4, beat both upper revenue and non-GAAP EPS guidance. Revenue exceeded the upper bound by about 4.9%, 14.2%, 24.0% and 8.7%. This upcycle sample is not a calibrated error distribution. FY2027 Q1 revenue $10.3–10.8bn and non-GAAP EPS $44–46 are guidance only; the October 29 release had not occurred at the cutoff.','已观察的四组独立季度配对（2026 财年第一至第四季）收入及非 GAAP 每股收益均超过指引上限，收入超出约 4.9%、14.2%、24.0%、8.7%。上行周期小样本不是已校准误差分布。2027 财年第一季收入 103–108 亿美元、非 GAAP 每股收益 44–46 美元仍只是指引；截至研究时点十月二十九日发布尚未发生。'),
'growth':('Revenue is prior revenue × (1+bit growth) × (1+ASP/mix change). Three explicit paths bracket structural reset, partial normalization and contract/cycle stress. Investor Day FY2028–30 targets include mid/high-teens sales growth, about 80% non-GAAP gross margin, 75% operating margin and 50% adjusted FCF margin. The structural case uses 74% after-SBC EBIT already in FY2027, an optimistic analyst choice before that target window, not full-year management guidance. Margins fade to 35%/20%/18%.','收入等于上年收入×（1+位元增长）×（1+均价／组合变化）。三条明确路径覆盖结构性重置、部分正常化及合同／周期压力。投资者日 2028–2030 目标包括十几个百分点中高段收入增长、约 80% 非 GAAP 毛利率、75% 营业利润率及 50% 调整自由现金流率。结构性情景从 2027 即采用扣股权薪酬后 74% 营业利润率，早于目标窗口，是乐观分析假设，并非管理层全年指引。最终利润率降至 35%／20%／18%。'),
'contracts':('July 3 RPO is $59,800m. Subsequent agreements have aggregate transaction price $31,300m; verified later RPO is null. Their $91,100m sum is not a reconciled later RPO, asset or annual sales forecast. Refundable customer deposits $1,500m are fully reserved; third-party collateral $5,000m is excluded. Delivery, pricing, counterparty, breach, renewal and enforcement risks remain; full executed contracts and price formulas are unavailable.','七月三日剩余履约义务为 59,800 百万美元，后续协议总交易价格为 31,300；已核实较晚 RPO 为空。91,100 的加总不是已对账的较晚 RPO、资产或全年销售预测。可退客户定金 1,500 全额预留，第三方抵押品 5,000 完全排除。交付、价格、对手方、违约、续约及执行风险仍在，完整合同与价格公式不可得。'),
'capital':('FCFF deducts own capex plus net JV funding less own D&A plus incremental operating working capital. Contractions do not release working capital in this conservative simplification. Sandisk takes roughly half Flash Ventures output and supports about half capital needs; all NAND wafers originate there. Wafer costs already embed JV depreciation, which is not added back. JV going-concern equity is not separately added to EV. Revenue-linked funding ratios are assumptions rather than physical wafer/node budgets.','FCFF 扣除自有资本开支加合资净投入、减自有折旧，再加增量经营营运资本。保守简化下收入收缩不释放营运资本。Sandisk 取得 Flash Ventures 约半数产出、支持约半数资本需求，全部 NAND 晶圆来自该体系。晶圆成本已含合资折旧，不再次加回；不将合资持续经营股权价值另加企业价值。收入比例资金投入是分析假设，不是物理晶圆／节点预算。'),
'cashConversion':('FY2026 CFO less own capex and net JV note advances is $11,219m, including $107m JV distributions classified in CFO; excluding them gives $11,112m. FY2025 comparable arithmetic is $62m before $176m investing distributions, or $238m including them. Classifications differ. FY2026 cash conversion also benefits from deposit, contract-liability and tax-payable growth. It is not recurring unlevered FCFF.','2026 经营现金流减自有资本开支与合资票据净垫款为 11,219 百万美元，其中含计入经营现金流的合资分配 107；排除后为 11,112。2025 同类计算在投资项分配 176 前为 62，包含后为 238。两年分类不同。2026 现金转化还受定金、合同负债及应付税增长支持，不是可重复无杠杆 FCFF。'),
'claims':('July 3 cash $4,762m reserves customer deposits $1,500m, assumed minimum cash $1,000m, current/noncurrent tax payables $1,286m/$258m and separate WDC indemnification $128m. Total reserves $4,172m leave $590m. Immediate face-value reserving is a conservative timing assumption, not legal payment dates. The annual $1,370m tax-payable change is not an ending balance. Forecast tax on future EBIT is separate.','七月三日现金 4,762 百万美元，预留客户定金 1,500、假设最低现金 1,000、流动／非流动应付税 1,286／258，及单独西部数据赔偿 128。共预留 4,172，剩余 590。立即按面值预留是保守时点假设，不代表法律付款日。年度应付税变化 1,370 不是期末余额，未来营业利润税另算。'),
'claimLimits':('Unrecognized tax benefits $323m plus interest/penalties are not automatically incremental to reserved tax balances. An optional $259m incremental tax stress may overlap. Legal expense $93m does not establish an unpaid balance; optional unpaid stress is explicitly conditional. The generic additional claim is an immediate reserve, reduces opening funding and equity exactly once, and cannot silently defer settlement. A $590m generic claim exhausts surplus; $590.001m creates a funding gap; $1,000m creates a $410m gap.','未确认税收利益 323 百万美元及利息罚款不可自动视为已预留税款之外增量。可选 259 增量税压力可能重叠。法律费用 93 不能证明未付款余额，可选未付压力为明确条件假设。一般额外请求权立即预留，期初资金与股权只扣一次，不能暗中延迟支付。590 的额外请求权耗尽余额，590.001 造成缺口，1,000 造成 410 缺口。'),
'bridge':('Nanya securities $1,777m receive an explicit 25% analyst haircut to $1,332.75m; they are not assumed sold to fund operations. Debt is zero. Operating leases remain expensed; contingent JV guarantees up to $923m are optional incremental stress, not automatic debt. Purchase, JV and lease commitment tables overlap with future costs/investment and must not be summed as new liabilities. The undrawn $1,500m revolver expires February 21, 2030 and is not assumed available across losses.','南亚证券 1,777 百万美元按明确分析假设折价 25% 至 1,332.75，不假设出售用于经营融资。债务为零。经营租赁继续费用化；最高 923 的合资担保仅为可选增量压力，并非自动债务。采购、合资及租赁承诺与未来成本／投资重叠，不可全部加作新负债。未使用 1,500 循环额度于 2030 年二月二十一日到期，不假定跨亏损期可用。'),
'awards':('The 155m diluted-share denominator is a weighted-average/forecast proxy, with 158m sensitivity. It is not the August 7 actual common count of 146.419001m or a point-in-time diluted ledger. RSU/PSU, maximum performance payouts, ESPP, repurchases and post-July changes are not fully reconstructed. Future SBC remains expensed; existing dilution is approximated in the denominator. The $14bn repurchase authorization is optional and is not a debt or automatic accretion.','1.55 亿稀释股数为加权平均／预测代理，另列 1.58 亿敏感性，不等于八月七日 1.46419001 亿实际普通股，也不是时点稀释账册。限制股、最高绩效支付、员工购股、回购及七月后变化尚未完整重建。未来股权薪酬费用化，既有稀释由分母近似。140 亿美元回购授权是可选权，不是债务或自动增厚。'),
'funding':('The economic funding pool starts at reserved-cash-adjusted surplus less any assumed guarantee call, then retains all FCFF by default. All three base paths are funded at annual resolution. Distributing every positive FCFF leaves the contract/cycle case with $5,118.215m unmet funding. No securities sale, debt, refinancing or issuance price is silently supplied. A gap withholds common equity and both per-share values; operating EV remains only a CONTINGENT_ON_UNMODELED_FUNDING diagnostic.','经济资金池从扣预留后余额减假设担保付款开始，默认保留全部 FCFF。三条默认路径按年度粒度均有资金支持。若分配全部正 FCFF，合同／周期压力情景有 5,118.215 百万美元未满足资金需求。没有暗含证券出售、债务、再融资或发行价格。出现缺口时普通股价值与两种每股值为空，经营企业价值仅为依赖未建模融资的条件诊断值。'),
'wacc':('WACC 11%/12%/14%, terminal growth 3%/3%/2.5%, cash tax 20%/22%/25% and terminal ROIC 25%/18%/15% are analyst assumptions. They are not current measured betas or rates. Losses receive no immediate tax benefit. Retained source sensitivity grids span WACC 9/11/12/13/14% and growth 2/2.5/3/4%; no probability distribution is calibrated.','WACC 11%／12%／14%、终值增长 3%／3%／2.5%、现金税 20%／22%／25% 及终值 ROIC 25%／18%／15% 均为分析假设，不是当前实测贝塔或利率。亏损无即时税益。保留的敏感性网格覆盖 WACC 9／11／12／13／14% 及增长 2／2.5／3／4%，没有校准概率分布。'),
 'terminal':('Terminal reinvestment is the larger of NOPAT × growth / ROIC and terminal revenue × net physical/JV floor plus incremental working capital. Floors are 7%/8%/11%, preserving final explicit own-capex + net-JV-funding − own-D&A continuity. These are analyst floors, not audited physical budgets. Implied reinvestment ROIC is about 11.30%/5.49%/2.94%; terminal shares of EV are 35.83%/22.03%/23.14%. A floor consuming all NOPAT invalidates valuation; below-base floors require separate efficiency justification.','终值再投资取两者较大：NOPAT×增长／ROIC，或终值收入×物理／合资净投入底线加增量营运资本。底线 7%／8%／11% 延续最后明确年度自有资本开支＋合资净投入−自有折旧，不是审计物理预算。隐含再投资 ROIC 约 11.30%／5.49%／2.94%，终值占企业价值 35.83%／22.03%／23.14%。底线耗尽 NOPAT 则估值无效；低于基准的底线需另证效率改善。'),
'uncertainty':('The wide output range reflects unresolved contract durability, price/mix and funding economics. Named scenarios have no assigned probabilities. Simulation defaults must be zero-width and uncalibrated, run only on request, recompute funding/claims/terminal floors for each trial, and exclude invalid or unfunded common-value trials with visible counts. A zero-width trial must reproduce the selected conditional case.','巨大估值差异反映未解决的合同持续性、价格／组合及融资经济。命名情景没有概率权重。模拟默认应为零宽度、未校准，仅按请求运行；每次重新计算资金、请求权及终值底线，并排除无效或未获融资的普通股价值试验且显示计数。零宽度应复现所选条件情景。'),
'audit':('Independent v3 recheck passed 114 saved cases, 15 reserve-boundary cases, 36 finite/type/domain probes and mutation checks. It repairs the v2 generic-claim funding inconsistency; default outputs are unchanged. Research approval is conditional and does not certify this integration or deployment. V1 model/bridge conclusions are superseded by v2 and the v3 claim correction; historical pending-review language is preserved in archives.','独立 v3 复核通过 114 个保存案例、15 个预留边界案例、36 个有限性／类型／取值域探针及变异测试，修复 v2 一般请求权融资不一致，默认输出不变。研究批准有条件，不认证本次集成或部署。v1 模型及桥接结论由 v2 与 v3 请求权修正取代；归档保留当时待复核措辞。')}
prose={k:{'en':v[0],'zh-Hans':v[1]} for k,v in pairs.items()}
# Public prose follows the same generic presentation keys as the incremental registry.
prose['capital']['en']+=' Edited annual reinvestment is subject to the explicit physical/JV/working-capital minimum; higher entered investment is retained.'
prose['capital']['zh-Hans']+=' 编辑后的年度再投资须满足明确物理／合资／营运资本最低需求，更高的输入投资予以保留。'
identity={'packageVersion':OUT.name,'version':'2026-10-19-sndk-conditional-v3','ticker':'SNDK','currency':'USD','informationAsOf':'2026-10-19','informationCutoff':inputs['information_cutoff'],'discountOrigin':'2026-07-03','reportedBalanceDate':'2026-07-03','valuationLabel':inputs['valuation_label'],'currentValuationEligible':False,'historicalBacktestEligible':False,'rankingEligible':False}
for key,path in [('source','v3/model-inputs.json'),('history','history-v3.json'),('audit','independent-audit-v3/recheck-results.json'),('fullReport','v2/RESEARCH-V2.md'),('auditReport','independent-audit-v3/REVIEW.md')]:identity[key+'Path']=BASE+path;identity[key+'SHA256']=sha(OUT/path)
identity.update({'packagedSourceSHA256':identity['sourceSHA256'],'originalSourceSHA256':sha(SRC/'v3/model-inputs.json'),'packagedHistorySHA256':identity['historySHA256'],'historyCSVPath':BASE+'history.csv','reportPath':BASE+'SNDK-v3.html','guidancePath':BASE+'guidance-comparisons-v3.json','provenancePath':BASE+'source-manifest.json','conditionalOutputsPath':BASE+'conditional-outputs-v3.json','packagingManifestPath':BASE+'packaging-manifest-v3.json'})
scenarios={s['name']:s for s in inputs['scenarios']};calculated={o['scenario']:o for o in outputs};default='Partial_normalization_illustrative'
def defaults(name):
 s=scenarios[name];b=inputs['capital_bridge']
 return {'minimumOperatingCash':b['minimum_operating_cash_assumption'],'securitiesHaircut':b['marketable_securities_haircut_assumption'],'additionalClaimReserve':b['additional_claim_reserve_assumption'],'incrementalUncertainTaxClaim':b['incremental_uncertain_tax_claim_assumption'],'incrementalUnpaidLegal':b['incremental_unpaid_legal_assumption'],'additionalJvGuaranteeCall':s['additional_jv_guarantee_call_assumption'],'terminalFundingFloor':s['terminal_net_physical_jv_funding_floor'],'distributePositiveFcff':int(s['distribution_policy']=='distribute_positive')}
